<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/functions/usuario.php'; requireLogin(); $pdo=getConnection(); $u=currentUser(); $erro='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $nome=trim($_POST['nome']??'');$senha=$_POST['senha']??'';if(mb_strlen($nome)<2){$erro='Informe um nome válido.';}else{$pdo->prepare('UPDATE usuario SET nome=? WHERE id_usuario=?')->execute([$nome,$u['id_usuario']]);if($senha!==''){if(strlen($senha)<6)$erro='A nova senha deve ter pelo menos 6 caracteres.';else{$pdo->prepare('UPDATE usuario SET senha=? WHERE id_usuario=?')->execute([password_hash($senha,PASSWORD_DEFAULT),$u['id_usuario']]);}}if(!$erro){$_SESSION['usuario']['nome']=$nome;$ok='Perfil atualizado com sucesso.';}}}
$historico=$pdo->prepare('SELECT o.id_ocorrencia,t.nome_tipo,o.data,o.horario,o.status FROM ocorrencia o JOIN tipo_ocorrencia t ON t.id_tipo=o.id_tipo WHERE o.id_usuario=? ORDER BY o.id_ocorrencia DESC LIMIT 10');$historico->execute([$u['id_usuario']]);$historico=$historico->fetchAll();$u=buscarUsuarioPorId($pdo,$u['id_usuario']);$page_title='SafeRoute — Meu perfil';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/navbar.php'; ?>
<main class="container page-main"><section class="page-hero"><span class="eyebrow">PERFIL</span><h1>Minha conta</h1><p>Gerencie seus dados e consulte seus registros.</p></section><?php if($erro): ?><div class="alert alert-error">⚠️ <?= htmlspecialchars($erro) ?></div><?php endif; ?><?php if($ok): ?><div class="alert alert-success">✅ <?= htmlspecialchars($ok) ?></div><?php endif; ?><div class="content-grid"><section class="card"><h2>Dados da conta</h2><form method="post"><div class="form-group"><label class="form-label">Nome</label><input class="form-control" name="nome" value="<?= htmlspecialchars($u['nome']) ?>" required></div><div class="form-group"><label class="form-label">Email</label><input class="form-control" value="<?= htmlspecialchars($u['email']) ?>" disabled></div><div class="form-group"><label class="form-label">Nova senha</label><input class="form-control" type="password" name="senha" placeholder="Deixe vazio para manter a atual"></div><button class="btn btn-primary">Salvar alterações</button></form></section><section class="card"><h2>Meu histórico</h2><table class="admin-table"><thead><tr><th>Tipo</th><th>Data</th><th>Status</th></tr></thead><tbody><?php foreach($historico as $h): ?><tr><td><?= htmlspecialchars($h['nome_tipo']) ?></td><td><?= htmlspecialchars($h['data']) ?></td><td><span class="admin-badge status-<?= htmlspecialchars($h['status']) ?>"><?= htmlspecialchars(ucfirst($h['status'])) ?></span></td></tr><?php endforeach; ?><?php if(!$historico): ?><tr><td colspan="3" class="admin-empty">Nenhum registro realizado.</td></tr><?php endif; ?></tbody></table></section></div></main><?php require_once __DIR__.'/../includes/footer.php'; ?>
